table = []

def before_insert(row):
    # BEFORE INSERT ON products FOR EACH ROW
    if row['price'] < 0:
        raise ValueError('price cannot be negative')

for row in [{'id': 1, 'price': 25.0}, {'id': 2, 'price': -5.0}]:
    try:
        before_insert(row)  # trigger fires first
        table.append(row)   # then the row is stored
        print('inserted: ' + str(row))
    except ValueError as e:
        print('rejected: ' + str(e))

triggers = {'check_price': {'enabled': True}}
table = []

def check_price(row):
    if row['price'] < 0:
        raise ValueError('price cannot be negative')

def insert(row):
    # the database consults the trigger registry first
    if triggers['check_price']['enabled']:
        check_price(row)  # trigger fires
    table.append(row)

# trigger ON: guardrail works
try:
    insert({'id': 1, 'price': -5.0})
except ValueError:
    print('trigger ON: rejected bad row')

# ALTER TRIGGER check_price DISABLE
triggers['check_price']['enabled'] = False
insert({'id': 2, 'price': -5.0})
print('trigger OFF: inserted bad row (no check!)')
